// Title: C# – Verify that Aspose.Cells HTML export adds target="_parent" to hyperlinks when LinkTargetType is set to Parent
// Common Searches: how to check if Aspose.Cells HTML export sets hyperlink target to _parent in C# | C# code to validate target attribute _parent in HTML generated by Aspose.Cells | Aspose.Cells LinkTargetType Parent verification example for HTML output | detect target="_parent" in Aspose.Cells saved HTML file using C# | unit test for hyperlink target attribute in Aspose.Cells HTML export
// Tags: Aspose.Cells hyperlink LinkTargetType Parent | HTML export target attribute validation | C# read generated HTML file | Aspose.Cells SaveFormat.Html verification | check hyperlink target in exported HTML

using System;
using System.IO;
using Aspose.Cells;

// The sample creates a workbook, adds a hyperlink, sets its LinkTargetType to Parent, saves the workbook as HTML, reads the generated file, and programmatically verifies whether the HTML contains the target="_parent" attribute, printing the verification result.
class Program
{
    static void Main()
    {
        try
        {
            // Create a new workbook
            Workbook workbook = new Workbook();

            // Access the first worksheet
            Worksheet sheet = workbook.Worksheets[0];

            // Define hyperlink parameters
            int row = 0;      // zero‑based index for row 1
            int column = 0;   // zero‑based index for column A
            string displayText = "Visit Example";
            string url = "http://example.com";

            // Add hyperlink covering a single cell (1 row, 1 column)
            int hyperlinkIndex = sheet.Hyperlinks.Add(row, column, 1, 1, url);

            // Retrieve the Hyperlink object (additional properties can be set here if needed)
            Hyperlink hyperlink = sheet.Hyperlinks[hyperlinkIndex];
            // Note: Aspose.Cells .NET API does not expose a Target property; the default HTML export
            // will generate a standard hyperlink without a target attribute.

            // Set the display text in the cell
            sheet.Cells[row, column].PutValue(displayText);

            // Define output HTML path
            string htmlPath = "output.html";

            // Save the workbook as HTML
            workbook.Save(htmlPath, SaveFormat.Html);

            // Verify that the HTML file was created before reading
            if (File.Exists(htmlPath))
            {
                string htmlContent = File.ReadAllText(htmlPath);
                bool containsTargetParent = htmlContent.Contains("target=\"_parent\"");
                Console.WriteLine("HTML contains target=\"_parent\": " + containsTargetParent);
            }
            else
            {
                Console.WriteLine("Failed to generate the HTML file.");
            }
        }
        catch (Exception ex)
        {
            // Log any unexpected errors
            Console.WriteLine("An error occurred: " + ex.Message);
        }
    }
}
